"""L17 source-bound drafts from actual inspection of all39 physical pages."""
from authoring_helpers import DraftBatch,formula
b=DraftBatch('W04-L17',4,'L17','Cartesian-space trajectory schemes',505,'robotics-integration-author-L17')
lin=formula('p(t)=p0+(pf−p0)t/T; pdot=(pf−p0)/T; pddot=0 for0<t<T',{'p,p0,pf':'Cartesian positions along the segment','t':'elapsed segment time','T':'positive segment duration','pdot,pddot':'velocity and acceleration'},{'p,p0,pf':'m','t,T':'s','pdot':'m/s','pddot':'m/s²'},['Affine interpolation with common time parameter; endpoint transitions are not included.'])
b.add(508,'path-space','Specify the tool path rather than infer it','What is directly specified by a Cartesian-space trajectory scheme?', ['Tool position and orientation as functions of time','Only each joint angle, leaving tool motion to forward kinematics','Only actuator torque versus time, without a pose path','Only the final pose, with no intermediate-motion rule'],0,'Cartesian planning states the desired tool motion in task coordinates; joint interpolation alone does not prescribe its spatial shape.',['This is the defining quantity in the slide.','This describes a joint-space scheme.','Torque histories belong to dynamics/control rather than the stated pose trajectory.','A trajectory requires a time-dependent motion rule, not only its endpoint.'],difficulty='easy')
b.add(508,'path-space','Joint interpolation does not ensure a straight tool line','Two joints each follow a linear function of time; what can be concluded about the tool path without examining the robot kinematics?', ['It need not be a straight line in Cartesian space','It must be a straight Cartesian line because both joint functions are linear','It must be a circular arc for every robot','Its orientation must remain fixed whenever its position changes'],0,'Forward kinematics is generally nonlinear in joint coordinates, so linear joint motion does not by itself fix the tool-path shape.',['The kinematic map determines the resulting spatial curve.','Linearity in joint coordinates does not imply linearity after a nonlinear map.','The curve depends on mechanism geometry and the motion.','Joint interpolation can change tool orientation as well as position.'],typ='scenario')
b.add(508,'via-geometry','Read a sequence of Cartesian via points','In the introductory XYZ diagram, what do the intermediate pose markers between START and END represent?', ['Via poses that describe intermediate tool motion along the planned path','Additional physical joints inserted into the manipulator','Only samples of actuator torque, with no position meaning','Alternative end goals that must all be reached at the same instant'],0,'The markers denote specified intermediate path poses, not a change to the robot mechanism.',['They constrain the planned tool motion between endpoints.','The diagram is a path description, not a linkage drawing.','The markers have spatial pose meaning.','Via points are ordered along the move rather than simultaneous alternative goals.'],typ='diagram',difficulty='easy')
b.add(509,'frame-workflow','Identify the pose reference','Which frame relation is used to describe the tool trajectory in this lecture?', ['The tool frame relative to the station frame','Every joint frame relative only to its own moving origin','The station frame relative to an unspecified camera without a transform','Only the tool origin’s distance from the base, with orientation discarded'],0,'The source states tool pose relative to the station frame, including position and orientation.',['This is the stated task-space relation.','A chain of link frames is not the specified task-pose description.','No such camera reference is introduced here.','Pose contains more than a scalar distance.'],typ='definition',difficulty='easy')
b.add(509,'frame-workflow','Locate inverse kinematics in the stated workflow','In the workflow described on this slide, when are joint configurations obtained from Cartesian pose samples?', ['At runtime at the path-update rate, through inverse kinematics','Only after the full motion has physically finished','By integrating actuator torques without using the geometry','By replacing every position sample with its time derivative'],0,'The described planner can define the Cartesian path first, then solve inverse kinematics for successive pose samples during execution.',['This is the sequence stated in the source.','Joint commands are needed during the move.','That is not the geometric pose-to-joint conversion.','Differentiation does not solve inverse kinematics.'],assumptions=['This is the described workflow, not a claim that every Cartesian planner postpones all inverse kinematics until runtime.'],difficulty='easy')
b.add(509,'frame-workflow','Explain the additional runtime work','Why can Cartesian path generation cost more runtime computation than evaluating a precomputed joint polynomial?', ['Each desired Cartesian pose may require an inverse-kinematics solve in addition to interpolation','Cartesian coordinates always have more components than every possible joint vector','Joint polynomials require no arithmetic at all','Cartesian interpolation removes the need to check branch or singularity conditions'],0,'The extra pose-to-joint conversion is the relevant computational step; actual runtime depends on the robot and implementation.',['This identifies the additional operation without claiming a universal benchmark.','Joint counts vary and dimension alone does not establish the cost.','Polynomial evaluation still requires arithmetic.','Those checks may still be necessary.'],assumptions=['Compare the source’s runtime-IK workflow with direct evaluation of a preplanned joint trajectory.'])
b.add(510,'blend-continuity','Distinguish velocity continuity from acceleration continuity','An LSPB profile joins a constant-acceleration parabola to a constant-velocity line; which continuity claim is justified when the join is matched?', ['Position and velocity can be continuous while acceleration jumps','Position, velocity and acceleration must all be continuous at every join','Velocity must jump because the position segments have different degrees','Acceleration is identically zero throughout the parabolic portions'],0,'A parabolic position segment has constant nonzero acceleration, while the line has zero acceleration; matching slopes makes velocity continuous but not acceleration.',['This distinguishes C1 matching from acceleration continuity.','The nonzero-to-zero acceleration transition need not be continuous.','Slopes can be matched despite different polynomial degrees.','A genuine parabolic blend provides acceleration.'],typ='source-reconciliation',conflict='Physical page510 claims linear/parabolic blends ensure continuity of acceleration; standard constant-acceleration blends generally have acceleration jumps at the joins.')
b.add(510,'blend-continuity','Identify each LSPB phase','Which pairing describes the interior linear region and the parabolic blend region?', ['Linear: constant velocity; parabolic: changing velocity under constant acceleration','Linear: constant acceleration; parabolic: constant velocity','Linear: zero velocity; parabolic: a discontinuous position jump','Both regions: a constant nonzero jerk'],0,'Differentiating a linear position gives constant velocity; differentiating a quadratic position gives a linearly changing velocity.',['These are the derivative properties used by the scheme.','This reverses the regions.','Neither a stop nor a position jump defines these portions.','Their ordinary within-region jerks are zero, not a common nonzero constant.'],typ='match',difficulty='easy')
b.add(511,'pose-parameterization','Count position and orientation components','In the six-component pose representation χ=[p;K], how many scalar components belong to p and K?', ['Three position components and three orientation parameters','Six position components and no orientation parameters','Three position components and nine independent rotation-matrix entries','One distance and five unconstrained rotation angles'],0,'The stated vector stacks a3-vector position and a3-parameter orientation representation.',['This gives the specified six entries.','The source includes orientation.','A3×3 matrix cannot be inserted as only three vector entries without a parameterization.','That is not the displayed representation.'],typ='definition',difficulty='easy',assumptions=['K denotes a three-parameter orientation representation; it is not a full3×3 matrix.'])
b.add(511,'pose-parameterization','Make the orientation notation dimensionally explicit','The slide labels K=ROT(k,θ) but also treats K as three entries; what convention makes χ=[p;K] a six-vector?', ['Define K=θk as a rotation vector, with unit axis k, and convert it to a rotation matrix when needed','Insert all nine entries of the rotation matrix into K while still calling χ six-dimensional','Use K as the scalar trace of the rotation matrix without changing the dimension','Treat the position vector p as a rotation matrix to cancel the extra entries'],0,'ROT commonly denotes a matrix; a rotation vector is a distinct three-parameter representation that must be explicitly defined rather than silently equated with that matrix.',['This supplies a consistent three-component convention.','Nine orientation entries plus three position entries give twelve scalar entries.','One trace value does not form the stated three-parameter orientation.','Changing the meaning of p does not resolve the notation.'],typ='source-reconciliation',conflict='Physical page511 uses ROT notation for K within a six-vector without specifying whether ROT denotes a matrix or a three-parameter representation.',assumptions=['Use angle θ in radians and unit axis k; different equivalent rotation vectors can represent the same orientation.'])
b.add(512,'orientation-wrap','Choose the shorter same-axis rotation','For a planar rotation about the same fixed axis from170° to−170°, which unwrapped endpoint produces the shortest20° interpolation?', ['Use190° instead of−170°','Use−170° directly and rotate−340°','Use−530° and rotate−700°','Keep170° as the endpoint because both signs denote the same angle'],0,'−170° and190° differ by a full turn;190°−170°=20°, whereas the direct numerical difference is−340°.',['This preserves the final orientation with the shorter same-axis turn.','This follows the longer wrapped-coordinate difference.','Adding extra full turns lengthens the path.','170° and−170° are not the same orientation.'],typ='numerical',difficulty='easy',steps=['Add360° to−170° to obtain the equivalent190°.','Compare190°−170°=20° with−170°−170°=−340°.'],assumptions=['Rotations are about one fixed axis and no extra winding is required.'],formulas=[formula('Δθ=θf_unwrapped−θ0; θf_unwrapped=θf+360°k',{'θ0':'initial angle','θf':'given final angle','k':'integer full-turn count','Δθ':'chosen angular displacement'},{'angles':'degrees','k':'dimensionless'},['Choose a representative appropriate to the permitted motion and winding constraints.'])])
b.add(512,'orientation-wrap','Do not generalize an absolute rotation-vector difference','For rotations about different noncommuting axes, why is minimizing the Euclidean distance between two absolute rotation vectors not a universal shortest-rotation rule?', ['The relative rotation must be obtained by composing the orientations; subtraction of their absolute parameter vectors need not encode that rotation','All3D rotations commute, so every subtraction gives the same path','Every orientation has exactly one axis-angle representation, so no branch choice exists','The length of a position vector determines the shortest orientation change'],0,'Axis-angle coordinates are not a global linear space of rotations; a relative matrix such as R_AᵀR_B, under a stated convention, describes the required orientation change.',['This respects the nonlinear rotation composition and its convention.','Rotations about different axes generally do not commute.','Axis-angle representations have equivalent branches.','Translational position length does not determine orientation distance.'],typ='source-reconciliation',assumptions=['R_A and R_B map the two body orientations into the same reference frame.'],conflict='Physical page512 suggests minimizing the difference of absolute angle-axis vectors gives the shortest rotation; this requires qualification beyond a same-axis or appropriate local representation.')
b.add(513,'workspace-hole','Reachable endpoints do not ensure a reachable segment','What failure is shown by the straight dashed segment through the inner hole of the annular workspace?', ['Both endpoints can be reachable while intermediate Cartesian points are unreachable','The endpoints must be unreachable whenever the segment is straight','Every point inside the outer circle is reachable regardless of the inner boundary','Slowing the same straight segment automatically fills the workspace hole'],0,'The inaccessible interior is outside the robot’s reachable set even if the segment begins and ends in the annulus.',['This is the geometric obstacle to the requested Cartesian path.','The diagram’s issue is the intermediate portion.','The inner boundary excludes some points.','Changing timing does not change geometric reachability.'],typ='diagram',difficulty='easy')
b.add(513,'workspace-hole','Test a two-link annular workspace','An unrestricted planar2R arm has lengths2 m and1 m; endpoints(2,0) m and(−2,0) m are reachable. Can its end point follow the straight segment between them?', ['No, because the segment contains radii below|2−1|=1 m','Yes, because both endpoint radii are below2+1=3 m','Yes, because the Cartesian distance4 m is below twice the maximum reach','No, because an endpoint radius2 m exceeds the maximum reach3 m'],0,'The reachable radial interval is1≤r≤3 m; the straight segment crosses r=0, which is not reachable.',['The inner-radius bound rules out the segment.','The outer bound alone is insufficient.','Total path length is not the pointwise reachability test.','The stated endpoint radius does not exceed3 m.'],typ='numerical',assumptions=['Ideal planar2R arm, unrestricted revolute joints, no other obstacles.'],steps=['Minimum radius is|l1−l2|=1 m and maximum radius is l1+l2=3 m.','The straight segment passes through the origin.','Since r=0<1 m, the complete segment is infeasible.'],formulas=[formula('|l1−l2|≤r≤l1+l2',{'l1,l2':'positive link lengths','r':'distance of endpoint from base'},{'l1,l2,r':'m'},['Unrestricted planar2R geometric reachability.'])])
b.add(514,'singular-speed','Explain large rates near singularity','Why can a near-singular configuration make a requested Cartesian motion hard to track?', ['Some task-velocity directions require very large joint rates, which can exceed actuator limits','Every Cartesian velocity requires exactly the same joint rate at a singularity','A singular Jacobian makes every joint position undefined','Increasing the update rate alone removes the singular geometric mapping'],0,'Loss of Jacobian rank or a small singular value can amplify the joint rates needed for particular task directions.',['This connects the geometry to a physical rate limit.','The effect depends on direction.','Joint positions remain coordinates even where the differential map is singular.','Faster updates do not change the instantaneous rank.'])
b.add(514,'singular-speed','Quantify directional rate amplification','In scaled velocity units, J=diag(1,0.01) and desired v=(0,1); what qdot solves v=Jqdot?', ['(0,100)','(0,0.01)','(1,0)','(0,1)'],0,'The second equation is0.01 qdot2=1, so qdot2=100.',['This solves the poorly conditioned direction.','This multiplies by the small entry instead of dividing.','The first axis cannot produce the requested second-axis velocity.','This would produce only0.01 in the second task component.'],typ='numerical',steps=['qdot1=0.','qdot2=1/0.01=100.'],assumptions=['Coordinates are scaled consistently; this is an illustrative local Jacobian, not a full robot specification.'],formulas=[formula('v=Jqdot',{'v':'scaled task-velocity vector','J':'local velocity map','qdot':'scaled joint-rate vector'},{'v,qdot':'compatible scaled velocity units','J':'dimensionless in this example'})])
b.add(514,'singular-speed','Distinguish a safe direction from a difficult one','For the same J=diag(1,0.01), which desired task velocity avoids the100-fold second-axis rate amplification?', ['v=(1,0)','v=(0,1)','v=(1,1)','v=(0,−1)'],0,'The first task direction maps through the unit entry and does not require motion in the small-gain direction.',['It gives qdot=(1,0).','It requires qdot2=100.','Its second component still requires qdot2=100.','It requires qdot2=−100.'],typ='scenario',assumptions=['Use the scaled local Jacobian shown in the question.'])
b.add(514,'singular-speed','Apply the joint-rate limit to path timing','With J=diag(1,0.01) and|qdot2|≤10, what is the largest permitted magnitude of the second task-velocity component?', ['0.1 in the scaled task-velocity units','10 in the scaled task-velocity units','100 in the scaled task-velocity units','0.001 in the scaled task-velocity units'],0,'|v2|=0.01|qdot2|≤0.01·10=0.1; slowing the path can respect this bound away from the exact singularity.',['This applies the local map and rate bound.','This ignores the small Jacobian entry.','This uses inverse amplification in the wrong direction.','This divides the allowed rate incorrectly.'],typ='numerical',steps=['Use v2=0.01qdot2.','Multiply the limit10 by0.01.'],assumptions=['The path direction is otherwise feasible and coordinates are consistently scaled.'],formulas=[formula('|v2|≤|J22|qdot2_max',{'v2':'second task velocity','J22':'local second-axis gain','qdot2_max':'joint-rate bound'},{'v2':'scaled task-rate units','J22':'dimensionless here','qdot2_max':'scaled joint-rate units'})])
b.add(515,'ik-branch','Require a continuous feasible joint branch','A path’s start and goal each have an inverse-kinematics solution; why can the requested Cartesian path still fail?', ['The available endpoint solutions may not connect through a continuous branch that respects joint limits','An inverse solution at the start proves every future point has the same solution','Two inverse branches are always interchangeable without changing joint position','Any reachable endpoint eliminates intermediate singularities'],0,'Endpoint existence is weaker than a continuous feasible joint trajectory along all intermediate poses.',['This is the branch and limit issue illustrated by the source.','A local endpoint solution does not prove the whole path.','Branch switching may require a discontinuity or a constrained transition.','Intermediate singularities remain possible.'],typ='scenario')
b.add(516,'runtime-joint','Read the generator’s runtime outputs','Which three joint quantities does the source’s trajectory generator provide at successive updates?', ['Position, velocity and acceleration','Only the final position and total elapsed time','Only actuator current, voltage and temperature','Mass, inertia and link length'],0,'The runtime generator evaluates the planned joint position and its first two derivatives.',['These are the stated trajectory outputs.','Intermediate reference values are required.','Those are actuator/electrical variables rather than the stated outputs.','Those describe model parameters, not the time-varying reference.'],typ='definition',difficulty='easy')
b.add(516,'runtime-joint','Evaluate a cubic and its derivatives','For θ(t)=1+2t+3t²+4t³ rad with t in seconds, what are θ,θdot,θddot at t=0.5 s?', ['3.25 rad,8 rad/s,18 rad/s²','3.25 rad,5 rad/s,6 rad/s²','2.75 rad,8 rad/s,18 rad/s²','3.25 rad,8 rad/s,12 rad/s²'],0,'The derivatives are2+6t+12t² and6+24t; substitution gives3.25,8,18.',['All three evaluations use the complete cubic.','This omits part of the cubic derivative and its time dependence.','This drops the4t³ contribution from position.','This omits the constant second-derivative term6.'],typ='numerical',steps=['θ(0.5)=1+1+0.75+0.5=3.25.','θdot(0.5)=2+3+3=8.','θddot(0.5)=6+12=18.'],formulas=[formula('θ=a0+a1t+a2t²+a3t³; θdot=a1+2a2t+3a3t²; θddot=2a2+6a3t',{'θ':'joint angle','t':'local segment time','a0,a1,a2,a3':'cubic coefficients','θdot,θddot':'first and second time derivatives'},{'θ,a0':'rad','t':'s','a1':'rad/s','a2':'rad/s²','a3':'rad/s³','θdot':'rad/s','θddot':'rad/s²'})])
b.add(517,'segment-time','Reset local time at a segment transition','A second polynomial segment starts at global time5 s; at global time5.2 s, which local time should evaluate its coefficients?', ['0.2 s','5.2 s','5.0 s','−0.2 s'],0,'Coefficients for a segment starting at its own time zero use elapsed time since that segment began.',['Subtract the start time:5.2−5.0=0.2.','This fails to reset the local time.','This substitutes the transition time rather than elapsed time.','The order of subtraction is reversed.'],typ='numerical',difficulty='easy',steps=['t_local=t_global−t_start.','t_local=5.2−5.0=0.2 s.'],formulas=[formula('t_local=t_global−t_start',{'t_local':'time since current segment began','t_global':'overall time','t_start':'start time of current segment'},{'all times':'s'})])
b.add([518,520],'blend-equation-conflict','Check the printed blend by differentiation','Let s=t−c with c constant; the printed position is x=xj+v(t−s)+(a/2)s², but printed velocity is v+as. What does differentiating that position actually give?', ['as, so the displayed position lacks the term needed to produce the extra v','v+as, because t−s has derivative1','v−as, because s decreases with t','v, because s² is constant when c is constant'],0,'ds/dt=1 and d(t−s)/dt=0, so the derivative is as; the pair is inconsistent when v≠0.',['This directly checks the literal expression.','t−s=c is constant, not a function with derivative1.','s=t−c increases at unit rate.','s varies even though c is constant.'],typ='source-reconciliation',assumptions=['Use the printed expression literally, with xj,v,a,c constant within the blend.'],conflict='Physical pages518 and520 display a blend position whose derivative omits v, while separately displaying velocity v+as.',formulas=[formula('s=t−c; d[xj+v(t−s)+(a/2)s²]/dt=as',{'s':'local blend time','t,c':'time and fixed offset','xj':'position constant','v':'incoming velocity','a':'constant blend acceleration'},{'s,t,c':'s','xj':'m','v':'m/s','a':'m/s²'})])
b.add([518,520],'blend-equation-conflict','Use a dimensionally and differentially consistent local blend','For position xb at the start of a blend and incoming velocity vb, which law has x(0)=xb,xdot(0)=vb and constant acceleration a?', ['x=xb+vb s+(1/2)a s²','x=xb+(1/2)a s² for every nonzero vb','x=xb+vb+(1/2)a s²','x=xb+vb s+a s²'],0,'Integrating constant acceleration once gives vb+as and twice gives xb+vb s+(1/2)as².',['This satisfies both initial conditions and the stated acceleration.','This forces the initial velocity to zero.','Adding velocity directly to position is dimensionally inconsistent.','This gives acceleration2a rather than a.'],typ='derivation',assumptions=['s is elapsed time from the blend start; this is an explicitly qualified consistent form, not an unannounced rewrite of the source.'],formulas=[formula('x=xb+vb s+(1/2)a s²; xdot=vb+as; xddot=a',{'x,xb':'current and initial blend position','s':'elapsed blend time','vb':'incoming velocity','a':'constant acceleration','xdot,xddot':'time derivatives'},{'x,xb':'m','s':'s','vb,xdot':'m/s','a,xddot':'m/s²'})])
b.add([518,520],'blend-equation-conflict','Evaluate a consistent local blend','With xb=2 m,vb=3 m/s,a=4 m/s² and s=0.5 s, what are position and velocity for x=xb+vb s+(1/2)a s²?', ['4 m and5 m/s','2.5 m and2 m/s','4.5 m and7 m/s','3.5 m and3 m/s'],0,'Position is2+1.5+0.5=4 m and velocity is3+2=5 m/s.',['Both the incoming velocity and acceleration contribute.','This drops the incoming-velocity terms.','This doubles the acceleration contribution.','This omits the acceleration contribution.'],typ='numerical',steps=['vb s=1.5 m and(1/2)a s²=0.5 m.','x=2+1.5+0.5=4 m.','xdot=3+4·0.5=5 m/s.'],assumptions=['Use the explicitly stated consistent local blend, not the inconsistent literal position expression on the slide.'],formulas=[formula('x=xb+vb s+(1/2)a s²; xdot=vb+as',{'x,xb':'current/initial blend position','vb':'initial blend velocity','a':'constant acceleration','s':'elapsed blend time'},{'x,xb':'m','vb,xdot':'m/s','a':'m/s²','s':'s'})])
b.save();print(len(b.questions),'L17 drafts through blend/runtime foundations.')
b.add(519,'shared-timing','Keep Cartesian component timing consistent','For a straight position segment from p0 to pf, why should all Cartesian components use the same progress parameter s(t)?', ['Then p(t)=p0+s(t)(pf−p0) stays on the segment','Each component must use a different duration to keep the path straight','A common progress parameter forces every coordinate displacement to be equal','Common timing eliminates the need for inverse kinematics'],0,'A single scalar multiplies the full displacement vector; independent progress laws can curve the spatial path even if every coordinate reaches its endpoint.',['This preserves the straight-line geometry.','Unequal progress laws generally change the path shape.','The displacement components retain their own values.','Joint configurations still need to be obtained for the desired poses.'],typ='derivation',assumptions=['0≤s(t)≤1; consider translational position separately from the chosen orientation representation.'],formulas=[formula('p(t)=p0+s(t)(pf−p0)',{'p,p0,pf':'current,start,final position vectors','s':'common scalar progress parameter'},{'positions':'m','s':'dimensionless'},['The same s multiplies every position component.'])])
b.add(519,'shared-timing','Recognize a curved path from unequal progress laws','A planar trajectory from(0,0) to(1,1) uses x=s and y=s² for0≤s≤1; which path results?', ['The parabola y=x², not the diagonal straight segment','The straight segment y=x because both endpoints match','A circle of radius1 because x and y use the same interval','A stationary point because the coordinates have unequal powers'],0,'Eliminating s gives y=x²; matching endpoint positions alone does not determine a straight path.',['This is the relation between the two coordinates.','Endpoint agreement does not impose equal component progress.','No circular constraint is present.','Both coordinates vary over the interval.'],typ='scenario',assumptions=['Coordinates are normalized by the same1 m scale; s is dimensionless.'])
b.add(520,'runtime-planning','Separate elapsed runtime from planned constants','Which quantities can be precomputed, while elapsed segment time must be updated during execution?', ['Segment durations, slopes and blend coefficients can be planned; the current elapsed time advances at runtime','The current elapsed time is fixed once during planning and never changes','Every coefficient must be recomputed solely because the clock advances','The segment slope is a time stamp rather than a velocity'],0,'Planning determines constants of the time law; runtime evaluation supplies the current time argument.',['This separates parameters from the changing independent variable.','A frozen elapsed time would repeatedly evaluate the same point.','Fixed-segment coefficients can be reused.','A slope has position-per-time units.'],typ='source-reconciliation',conflict='Physical page520 loosely says time was calculated at planning time; planned durations/offsets and current elapsed runtime must be distinguished.')
b.add(521,'pose-transform','Construct a homogeneous transform from a pose','With R mapping tool coordinates to station coordinates and p the tool origin in station coordinates, which homogeneous transform maps a tool point to station coordinates?', ['T=[[R,p],[0,0,0,1]]','T=[[Rᵀ,p],[0,0,0,1]] without changing p','T=[[R,0],[pᵀ,1]]','T=[[R,p],[0,0,0,0]]'],0,'The upper block applies rotation and translation, while the bottom row preserves the homogeneous coordinate.',['This implements x_station=R x_tool+p.','Transposing only R changes the rotation direction without the required inverse translation.','Translation belongs in the last column for column homogeneous vectors.','The final homogeneous coordinate must remain1.'],typ='derivation',assumptions=['Column-vector convention is explicitly stated here because the displayed source transform labels are not fully consistent with its earlier tool/station notation.'],formulas=[formula('[x_S;1]=T_ST[x_T;1]; x_S=R_ST x_T+p_ST',{'x_S,x_T':'point coordinates in station and tool frames','R_ST':'rotation mapping tool components to station components','p_ST':'tool-origin position in station coordinates','T_ST':'homogeneous tool-to-station transform'},{'x_S,x_T,p_ST':'m','R_ST':'dimensionless','T_ST':'rotation and translation blocks have their respective units'})])
b.add(521,'finite-differences','Evaluate successive backward differences','At times0,0.1,0.2 s, q equals0,0.01,0.04 rad; what backward-difference velocity at0.2 s and acceleration from successive velocity estimates result?', ['0.3 rad/s and2 rad/s²','0.4 rad/s and2 rad/s²','0.3 rad/s and3 rad/s²','0.03 rad/s and0.2 rad/s²'],0,'The last two interval velocities are0.1 and0.3 rad/s; their difference divided by0.1 s is2 rad/s².',['This uses the two stated backward-difference steps.','0.4 is the analytic endpoint velocity for q=t², not this backward estimate.','This divides the latest velocity by time instead of differencing velocities.','This misses factors from dividing by the sample interval.'],typ='numerical',steps=['v1=(0.01−0)/0.1=0.1 rad/s.','v2=(0.04−0.01)/0.1=0.3 rad/s.','a2=(0.3−0.1)/0.1=2 rad/s².'],formulas=[formula('v_k=(q_k−q_(k−1))/Δt; a_k=(v_k−v_(k−1))/Δt',{'q_k':'joint angle at sample k','v_k':'backward-difference velocity estimate','a_k':'difference of successive estimated velocities divided by time','Δt':'positive uniform sample interval'},{'q':'rad','v':'rad/s','a':'rad/s²','Δt':'s'})])
b.add(521,'finite-differences','Avoid a false velocity from angle wrapping','A continuous positive rotation is recorded as179° then−179° after0.1 s; what rate follows after correctly unwrapping the second angle to181°?', ['+20°/s','−3580°/s','−20°/s','+3580°/s'],0,'The continuous angular change is181°−179°=2°, not the wrapped-coordinate jump−358°.',['2°/0.1 s=20°/s.','This uses the discontinuous wrapped difference.','This reverses the known direction.','This uses the large wrapped magnitude with a positive sign.'],typ='numerical',assumptions=['The physical motion is known to be the short positive rotation; branch continuity is maintained.'],steps=['Choose the equivalent181° representation.','Compute(181−179)/0.1=20°/s.'],formulas=[formula('ω_est=(θ_k_unwrapped−θ_(k−1))/Δt',{'ω_est':'angular-rate estimate','θ_k_unwrapped':'continuous representative of latest angle','θ_(k−1)':'previous angle','Δt':'sample interval'},{'angles':'degrees','Δt':'s','ω_est':'degrees/s'})])
b.add(521,'finite-differences','Understand the limitation of numerical differentiation','Why can unrelated inverse-kinematics branch choices corrupt the finite-difference velocity?', ['The joint samples may jump between branches even though the desired tool path is smooth','Finite differences are independent of the actual joint position samples','A shorter sample interval always removes a branch jump','Every pair of inverse solutions represents the same joint configuration'],0,'The derivative estimate divides the change in joint coordinates by time; an artificial branch jump can create a very large apparent rate.',['This identifies a continuity requirement on the samples.','The samples are the numerator of the estimate.','Dividing a fixed jump by a smaller interval can make the false rate larger.','Different solutions can correspond to distinct configurations.'],typ='scenario')
b.add(522,'robot-commands','Read the illustrative LINEARLY command','In this lecture’s illustrative syntax, what does MOVE ARM TO C LINEARLY request?', ['Cartesian straight-line interpolation toward pose C','A straight line in every joint angle with no task-space requirement','A move through every named via point automatically','A proof that the path to C is collision-free'],0,'LINEARLY denotes the Cartesian interpolation mode in the displayed language example.',['This is the intended interpretation of the command.','That is a different trajectory-space requirement.','Via points must be specified separately.','Interpolation syntax alone does not certify obstacle clearance.'],difficulty='easy',assumptions=['Interpret the lecture’s example syntax, not a command standard shared by all robot controllers.'])
b.add(522,'robot-commands','Distinguish a via-point command','What additional path information does MOVE ARM TO C VIA B supply compared with MOVE ARM TO C?', ['An intermediate via pose B before the final pose C','A new physical revolute joint called B','A guaranteed zero-acceleration profile throughout the move','The inverse of the final pose C'],0,'VIA names an intermediate point or pose used to constrain the planned motion.',['This is the stated role of B.','A program path marker does not alter the mechanism.','The command does not supply that acceleration guarantee.','B is an intermediate pose, not a transform inverse.'],difficulty='easy',assumptions=['Use the illustrative command meanings shown in the source.'])
b.add(523,'dynamic-limits','Qualify a fixed acceleration limit','Why is a fixed maximum acceleration in simple trajectory planning a simplification?', ['Achievable acceleration depends on the current dynamics and actuator torque-speed limits','Every actuator has a constant acceleration limit that is independent of load','Torque-speed characteristics determine only geometric reachability','Joint acceleration depends only on the number of via points'],0,'Mass/inertia, velocity, gravity and available actuator effort influence which acceleration is achievable at a state.',['This matches the source’s dynamics-aware warning.','A load-independent constant bound need not describe the real actuator/robot.','Torque-speed limits concern effort and motion feasibility, not just geometry.','Via-point count alone does not determine the force balance.'])
b.add([523,524],'dynamic-limits','Check a state-dependent acceleration bound','At one operating speed a single joint can supply at most12 N·m; its positive gravity/load torque is8 N·m and inertia is2 kg·m². With other terms zero, what is the greatest positive acceleration?', ['2 rad/s²','6 rad/s²','10 rad/s²','4 rad/s²'],0,'From τ=Iα+8, the available accelerating torque is12−8=4 N·m, so α_max=4/2=2 rad/s².',['This subtracts the load before dividing by inertia.','This ignores the load torque.','This adds the load to the actuator limit.','This reports net torque as though it were acceleration.'],typ='numerical',assumptions=['The12 N·m limit applies at the specified speed; the joint direction and load sign are fixed as stated.'],steps=['Net positive accelerating torque=12−8=4 N·m.','α_max=4/2=2 rad/s².'],formulas=[formula('α_max=(τ_max−τ_load)/I',{'α_max':'largest positive acceleration at this state','τ_max':'available positive actuator torque','τ_load':'positive opposing load torque','I':'positive effective inertia'},{'α_max':'rad/s²','τ_max,τ_load':'N·m','I':'kg·m²'})])
b.add(524,'path-timing','Separate path geometry from minimum-time timing','In the source’s more general timing problem, what is held fixed while timing is optimized?', ['The spatial path, with motion timing constrained by dynamics and actuator characteristics','Every joint acceleration, independent of available torque','Only the final arrival time, with no prescribed spatial path','Every obstacle model is removed from the problem'],0,'The stated task is to move along a given path in minimum time while respecting the robot and actuator limits.',['This is a path-parameterization problem with dynamics constraints.','Acceleration is part of the feasible motion, not an arbitrary immutable maximum.','The source specifies the path as given.','The timing problem does not justify ignoring environmental constraints.'],difficulty='easy')
b.add(524,'path-timing','Understand conservative timing','What trade-off can follow from choosing one conservative acceleration bound for the whole path?', ['The motion may respect limits but underuse the robot’s speed capability in easier regions','The robot is guaranteed to achieve the minimum possible time','The chosen bound automatically proves collision avoidance','The geometry of the spatial path must become a straight line'],0,'A uniform bound chosen for a difficult state can be lower than the available capability elsewhere.',['This is the source’s reason to consider dynamics-aware timing.','Conservatism does not establish time optimality.','Effort limits and obstacle clearance are different constraints.','Timing does not force a new path shape.'],typ='scenario')
b.add(525,'collision-path','Check configurations rather than endpoints alone','Which condition is required for a collision-free manipulator path?', ['Every traversed robot configuration must avoid obstacles and respect the stated constraints','Only the start and final tool points must lie outside obstacles','The end-effector line must be straight, regardless of where other links pass','Every via point must have the same orientation'],0,'A valid motion must account for the robot’s geometry along the whole path, not only the two tool endpoints.',['This includes intermediate configurations and constraints.','A link or intermediate pose can still collide.','A straight tool line can collide or bring another link into collision.','Equal orientation is not the definition of collision freedom.'],typ='scenario')
b.add(526,'collision-models','Identify required geometry models','Which models does the source say the collision-free planner needs?', ['The manipulator, workspace and obstacles','Only the tool’s final orientation','Only the actuator voltage-current curve','Only the name of the programming language'],0,'Geometric planning requires a representation of the robot and its environment.',['These provide the stated geometric information.','A goal orientation alone is insufficient.','Actuator curves do not describe obstacle geometry.','A language name supplies no collision model.'],typ='definition',difficulty='easy')
b.add(526,'planning-approaches','Match two collision-planning approaches','Which pairing matches the source’s two approaches?', ['Free-space graph: search connected feasible regions; potential field: goal attraction and obstacle repulsion','Free-space graph: ignore connectivity; potential field: obstacle attraction and goal repulsion','Free-space graph: store only actuator torques; potential field: solve only forward kinematics','Both approaches: require every via point to be manually specified'],0,'The slide contrasts connectivity search with motion guided by artificial attractive and repulsive effects.',['This preserves both mechanisms.','This reverses the field directions and removes the graph’s defining property.','These are not the geometric planning roles described.','The stated aspiration is automatic path/via-point selection.'],typ='match',difficulty='easy')
b.add(526,'potential-minima','Recognize a potential-field local minimum','Away from the goal, attractive and repulsive artificial forces cancel and the local descent direction vanishes; what can happen?', ['The planner can stall at a local minimum instead of reaching the goal','Cancellation proves that the current point is the goal','The obstacle must disappear from the model','The global shortest path has necessarily been found'],0,'A stationary point of the artificial field can be different from the goal; the source explicitly lists local minima as a limitation.',['This is the identified failure mode.','Zero net artificial force does not uniquely identify the goal.','Force balance does not remove an obstacle.','A local stationary point does not establish global path optimality.'],typ='scenario')
b.add(526,'dimension-complexity','State a precise source for exponential growth','A grid uses m discrete values for each of n joint coordinates; what explains a possible exponential growth with joint count?', ['The grid contains m^n configurations before any pruning','Every graph search takes2^N time where N is the number of supplied nodes','A robot with n joints always has exactly n² collision-free paths','Potential fields remove all dimension-dependent costs'],0,'The Cartesian product of n sets of m values has m^n combinations; this is a precise representation-based interpretation, not a universal complexity theorem for every graph algorithm.',['This states the combinatorial source of growth.','Complexity in an already supplied graph depends on the search algorithm; that universal claim is false.','There is no such fixed path count.','Potential fields do not erase every modelling or dimensional cost.'],typ='source-reconciliation',conflict='Physical page526 broadly attributes exponential joint-count complexity to graph planning; the representation and problem assumptions must be stated.',formulas=[formula('N_grid=m^n',{'N_grid':'number of grid configurations','m':'values per coordinate','n':'number of independent joint coordinates'},{'all quantities':'dimensionless counts'},['Full regular grid without pruning.'])])
b.add(526,'dimension-complexity','Compute the grid-size increase','At10 samples per joint, how does a full grid change from two joints to six joints?', ['From100 to1,000,000 configurations, a10,000-fold increase','From20 to60 configurations, a3-fold increase','From100 to600 configurations, a6-fold increase','From100 to10,000 configurations, a100-fold increase'],0,'10²=100 and10⁶=1,000,000; their ratio is10⁴=10,000.',['This uses the product of coordinate choices.','This counts values additively rather than combinations.','This multiplies the old grid by the new joint count instead of adding dimensions.','10,000 is the four-joint grid, not the six-joint grid.'],typ='numerical',difficulty='easy',steps=['N2=10²=100.','N6=10⁶=1,000,000.','N6/N2=10⁴=10,000.'],formulas=[formula('N=m^n',{'N':'full-grid configurations','m':'samples per coordinate','n':'joint count'},{'N,m,n':'dimensionless counts'})])
b.save();print(len(b.questions),'L17 drafts through planning and collision constraints.')
example='Planar Cartesian pose starts at(x,y,φ)=(0.700 m,0.200 m,0°) and ends at(0.300 m,−0.400 m,60°) over4.0 s; use affine component interpolation with this unwrapped planar angle.'
b.add([527,528],'worked-linear-law','Form the example’s time laws','For the source’s4 s move from(0.700,0.200,0°) to(0.300,−0.400,60°), which time laws are correct?', ['x=0.700−0.100t; y=0.200−0.150t; φ=15t','x=0.700+0.100t; y=0.200+0.150t; φ=15t','x=0.700−0.400t; y=0.200−0.600t; φ=60t','x=0.300−0.100t; y=−0.400−0.150t; φ=60+15t'],0,'Each slope is final minus initial divided by4 s; the intercept is the initial coordinate.',['These satisfy both endpoint conditions at t=0 and4 s.','The spatial slope signs are reversed.','The displacement has not been divided by the duration.','The final pose has incorrectly been used as the initial intercept.'],typ='numerical',assumptions=[example,'t is elapsed time in seconds; x,y are metres and φ is degrees.'],steps=['xdot=(0.300−0.700)/4=−0.100 m/s.','ydot=(−0.400−0.200)/4=−0.150 m/s.','φdot=(60−0)/4=15°/s.'],formulas=[lin,formula('φ(t)=φ0+(φf−φ0)t/T',{'φ,φ0,φf':'current,initial,final unwrapped planar orientation','t,T':'elapsed time and duration'},{'angles':'degrees','t,T':'s'})])
b.add([529,530],'worked-midpoint','Evaluate the complete midpoint pose','What is the Cartesian pose at t=2.0 s in the4 s source example?', ['(0.500 m,−0.100 m,30°)','(0.500 m,0.100 m,30°)','(0.300 m,−0.400 m,60°)','(0.200 m,−0.300 m,30°)'],0,'At half the duration, each affine coordinate is the arithmetic midpoint of its endpoints.',['All three coordinates are midway between their endpoints.','The y midpoint is(0.200−0.400)/2=−0.100, not positive.','This is the final pose at4 s.','These are displacement contributions rather than the absolute position.'],typ='numerical',difficulty='easy',assumptions=[example],steps=['x(2)=0.700−0.100·2=0.500 m.','y(2)=0.200−0.150·2=−0.100 m.','φ(2)=15·2=30°.'],formulas=[lin])
b.add([529,531],'worked-rates','Keep linear and angular velocity units distinct','Which velocity vector and angular-rate conversion match the example?', ['(−0.100 m/s,−0.150 m/s,15°/s), with15°/s=π/12 rad/s','(−0.100 m/s,−0.150 m/s,15 rad/s), with no conversion needed','(−0.400 m/s,−0.600 m/s,60°/s)','(−0.100 m/s,+0.150 m/s,π/12°/s)'],0,'The spatial slopes are negative, while orientation increases15 degrees per second; multiplying byπ/180 givesπ/12 radians per second.',['This preserves the mixed physical units and converts the angle rate correctly.','The numeric value15 is in degrees per second, not radians per second.','These use total coordinate changes instead of dividing by4 s.','The y sign and angular unit conversion are wrong.'],typ='numerical',steps=['Divide each endpoint change by4 s.','15·π/180=π/12 rad/s.'],assumptions=[example],formulas=[formula('ω_rad=ω_deg π/180',{'ω_rad':'angular speed in radians per second','ω_deg':'numeric angular speed in degrees per second'},{'ω_rad':'rad/s','ω_deg':'degrees/s'})])
b.add([531,539],'interior-acceleration','Do not infer a rest-to-rest acceleration profile','The example’s acceleration arrays are zero; what do they establish?', ['Zero acceleration in the specified constant-rate segment, not a complete physical transition from and back to rest','That a nonzero constant velocity can be reached instantaneously with bounded zero acceleration from rest','That no actuator effort is needed even under gravity or load','That inverse kinematics must return zero joint acceleration for every robot'],0,'The displayed affine motion omits the start/stop blends; it does not model the acceleration needed to join an external rest condition.',['This is the correct scope of the zero derivative.','A change of velocity requires a transition not included in the affine interior.','Zero kinematic acceleration does not imply zero load-balancing effort.','A nonlinear kinematic map can require joint accelerations even at constant Cartesian velocity.'],typ='source-reconciliation',conflict='The code and output show zero acceleration for all listed samples of a constant-rate segment; those values do not model physical rest-to-rest endpoint transitions.')
b.add([527,528,540],'line-length-speed','Find spatial speed without mixing orientation units','For the example, what are the translational path length and constant translational speed?', ['√0.52 m≈0.7211 m and√0.0325 m/s≈0.1803 m/s','60.7211 m and15.1803 m/s after adding the angle change','0.4 m and0.1 m/s because only x changes the path length','1.0 m and0.25 m/s by adding absolute x and y changes'],0,'The straight-line displacement is(−0.4,−0.6) m, so its Euclidean length is√(0.16+0.36); divide by4 s for speed.',['This uses the spatial Euclidean norm only.','Degrees cannot be added to metres to obtain a translational length.','The y displacement also contributes.','That is an axis-aligned path length, not the straight-line length.'],typ='numerical',assumptions=[example],steps=['Δp=(−0.4,−0.6) m.','Length=√(0.4²+0.6²)=√0.52 m.','Speed=√0.52/4=√0.0325 m/s.'],formulas=[formula('L=√(Δx²+Δy²); speed=L/T',{'L':'straight translational path length','Δx,Δy':'Cartesian displacements','T':'positive duration','speed':'constant translational speed'},{'L,Δx,Δy':'m','T':'s','speed':'m/s'})])
b.add([530,536,537],'zero-crossing','Find the continuous zero crossing between samples','With y(t)=0.200−0.150t m, when does the path cross y=0?', ['t=4/3 s, between the1.2 s and1.4 s samples','t=1.2 s exactly because it is the last positive listed sample','t=1.4 s exactly because it is the first negative listed sample','t=2 s because every coordinate crosses zero at the midpoint'],0,'Solving0.200−0.150t=0 gives t=4/3 s; the printed table brackets rather than exactly samples it.',['This solves the continuous trajectory equation.','At1.2 s,y=0.020 m remains positive.','At1.4 s,y=−0.010 m is already negative.','The midpoint y is−0.100 m, not zero.'],typ='numerical',steps=['Set0.200−0.150t=0.','t=0.200/0.150=4/3 s.','Compare1.2<4/3<1.4.'],formulas=[lin],assumptions=[example])
b.add([533,534,536],'sample-grid','Count samples and update intervals','For the displayed t=np.arange(0,tf+dt,dt) with tf=4.0 and dt=0.2, how many motion samples and elapsed update intervals are produced in this example?', ['21 samples and20 intervals','20 samples and20 intervals','21 samples and21 intervals','22 samples including4.2 s'],0,'The actual array runs from0 through4.0 in0.2 increments; both endpoints are samples, so there is one more sample than interval.',['This matches the code and printed table.','This drops one endpoint sample.','Intervals connect adjacent samples, so there are only20.','The arange stop4.2 is excluded in this executed example.'],typ='code_output',difficulty='easy',assumptions=['Use the exact displayed parameters and verified output; do not generalize floating-step arange endpoint behaviour to all parameter choices.'])
b.add(534,'sample-grid','Interpret the endpoint padding carefully','Why does the example use tf+dt as the stop argument rather than tf?', ['To include the desired4.0 s endpoint in this particular half-open arange grid','Because arange always includes its stop argument','Because a trajectory must continue through4.2 s','Because adding dt changes the physical duration from4.0 s to4.2 s'],0,'arange normally excludes the stop value; padding the stop allows4.0 to appear for this grid, but floating-step endpoint reliability still requires checking.',['This explains the code’s intention and observed result.','The stop is not generally included.','The printed result ends at4.0 s.','The declared motion duration remains4.0 s.'],typ='code',assumptions=['The exact NumPy expression and observed array are the subject; robust general code should check its generated endpoints.'])
b.add([533,534],'sample-grid','Convert the update interval to a frequency','A path-update interval of0.2 s corresponds to which nominal update frequency?', ['5 Hz','0.2 Hz','20 Hz','2 Hz'],0,'Frequency is the reciprocal of the interval:1/0.2=5 updates per second.',['This is the reciprocal time scale.','This repeats the interval without taking the reciprocal.','This would correspond to0.05 s.','This would correspond to0.5 s.'],typ='numerical',difficulty='easy',steps=['f=1/Δt.','f=1/0.2 s=5 Hz.'],formulas=[formula('f=1/Δt',{'f':'nominal update frequency','Δt':'positive update interval'},{'f':'Hz','Δt':'s'})])
b.add(534,'numpy-array-derivatives','Understand ones_like and zeros_like','What does np.ones_like(t)*((x2−x1)/tf) produce in the displayed code?', ['An array with t’s shape containing the constant x-velocity at every sample','A scalar containing only the final x position','A numerical finite difference of x that has one fewer sample','An array of elapsed times multiplied by x displacement'],0,'ones_like creates an array of ones with the time array’s shape; multiplying by the constant slope repeats that analytic velocity.',['This matches the vectorized expression.','The result is an array of velocities, not one position.','No differences of neighbouring x values are taken.','The array entries before multiplication are ones, not the time values.'],typ='code_output',difficulty='easy')
b.add(534,'numpy-array-derivatives','Distinguish assigned derivatives from measured derivatives','Why are the acceleration arrays zero in the code?', ['The program directly assigns np.zeros_like(t) for the analytic linear-segment acceleration','The program measures a physical robot and finds its acceleration zero','The program solves inverse dynamics and proves no torque is needed','The program estimates acceleration by differencing noisy joint measurements'],0,'The zero arrays encode the derivative of the chosen affine trajectory; they are not sensor measurements or a dynamics solution.',['This is the operation actually printed.','No sensor interface or measured data is present.','No inertia or force model is used.','No joint measurements or numerical differencing appear in this code.'],typ='code',difficulty='easy')
b.add([534,535,536],'printed-row','Trace one non-midpoint table row','At index7 of the displayed0.2 s time array, which printed t,x,y,φ values appear?', ['1.4,0.560,−0.010,21.0','1.2,0.580,0.020,18.0','1.4,0.560,0.010,21.0','7.0,0.000,−0.850,105.0'],0,'Zero-based index7 gives t=1.4; substituting into the affine laws yields x0.560,y−0.010,φ21.0.',['This matches the index, arithmetic and printed formats.','This is index6 rather than7.','The y value has already crossed below zero.','This treats the array index as elapsed seconds.'],typ='code_output',assumptions=[example,'Use zero-based NumPy indexing and the displayed formatting.'])
b.add(535,'formatting','Read the table’s precision rules','Which formatting does the printed Python loop apply?', ['Time and orientation to one decimal; x and y to three decimals','Every value to an integer with no decimal places','Time to three decimals and x and y to one decimal','All arrays are printed as hexadecimal strings'],0,'The f-strings use .1f for time and φ and .3f for the two position components.',['This matches the visible format specifiers.','The code requests decimal fractional digits.','This swaps the visible precision choices.','The f format is fixed-point decimal.'],typ='code_output',difficulty='easy')
b.add([534,535,537,538,539,540],'code-versus-figures','Separate printed code from plotted output','What is missing from the printed program needed to reproduce the later graph figures directly?', ['Plotting commands; the shown program generates arrays and prints a table but contains no plot calls','The NumPy import, which is not shown anywhere','The time vector, which the program never defines','Every Cartesian position formula, which appears only in the graphs'],0,'The supplied code pages contain NumPy array construction and print statements; the subsequent plots require additional plotting code not printed there.',['This identifies the genuine omission without pretending the plotted figures were produced by the printed script alone.','import numpy as np is explicitly shown.','t is explicitly constructed with arange.','x,y,φ are explicitly calculated.'],typ='source-reconciliation',conflict='Physical pages537–540 show plotted outputs, but the printed code on534–535 contains no plotting library import or plotting calls.')
b.add(537,'plot-interpretation','Read the three position plots','Which trend is shown by the example’s x,y and orientation plots?', ['x and y decrease linearly while orientation increases linearly','x and y increase while orientation stays constant','All three curves are parabolas because the figure uses multiple samples','All three coordinates have the same numerical slope'],0,'The source plots represent x=.7−.1t,y=.2−.15t andφ=15t; sample markers do not change those linear laws.',['This matches the signs and straight shapes.','This reverses the spatial directions and ignores rotation.','Sampling a line does not make it quadratic.','The slopes are−.1,−.15 and15 in their respective units.'],typ='diagram',difficulty='easy')
b.add(538,'plot-interpretation','Do not mistake an autoscaled velocity axis for changing velocity','The x-velocity graph has a narrow vertical axis around−0.100 and a horizontal trace; what does it show?', ['Constant negative x-velocity, despite the axis range surrounding that value','Acceleration because the axis has several labelled ticks','A sign change because the graph includes values above and below the trace','Zero x-velocity because a horizontal line means no motion'],0,'A horizontal velocity-time trace means the velocity is constant; its vertical value is−0.100, not zero.',['This reads both the trace shape and its ordinate.','Axis ticks do not turn a velocity plot into acceleration.','The data trace does not cross zero.','A horizontal position plot would indicate rest; a horizontal nonzero velocity plot does not.'],typ='diagram')
b.add(540,'orientation-versus-tangent','Separate tool orientation from the direction of travel','The XY path moves down-left while the plotted tool-axis arrows point generally right/up; is that necessarily inconsistent?', ['No, tool orientation can vary independently of the translational path tangent','Yes, tool orientation must always equal the direction of translation','Yes, a straight Cartesian position path requires fixed orientation','No, because the arrows must instead be joint torque vectors'],0,'The trajectory specifies both position and orientation; a tool may translate in one direction while pointing in another.',['The arrows can encode the independently specified orientation.','There is no universal alignment requirement.','Straight translation does not require constant orientation.','The example’s arrows show orientation, not a torque result.'],typ='diagram',assumptions=['Interpret arrows as the tool orientation illustrated by the source, not as a claim about a particular contact constraint.'])
b.add([537,540],'orientation-versus-tangent','Do not infer a joint angle from a task-angle label','The plot labels orientation θ while the code calls it φ; what can be concluded without a specified robot and inverse-kinematics solution?', ['It is the plotted planar task orientation; no particular joint-angle history has been established','It must be joint1’s angle for every possible robot','It must equal the sum of all joint torques','It proves that every joint rotates at15°/s'],0,'The example is a Cartesian pose interpolation; renaming the plotted orientation does not supply a mechanism or solve its joints.',['This preserves the distinction between task coordinates and joint coordinates.','The relation depends on the robot’s kinematics.','Angles and torques are different quantities.','The task rate alone does not determine all joint rates.'],typ='source-reconciliation',conflict='The orientation plot uses θ where the printed interpolation code uses φ; both denote the task orientation here, not a demonstrated individual joint angle.')
b.add([533,534,540],'example-scope','Identify what this interpolation program does not verify','Which claim is not established by the displayed arrays, table and straight-line plot?', ['That a particular physical manipulator can execute the path without collision, singularity or actuator-limit violation','That the generated x coordinate decreases from0.700 to0.300','That the generated orientation increases from0° to60°','That the generated interior Cartesian acceleration is zero'],0,'The program has no robot geometry, inverse kinematics, obstacle model or actuator dynamics, so geometric interpolation alone cannot verify execution feasibility.',['Those checks need information and computations absent from the example.','That endpoint change is explicitly encoded and printed.','That orientation change is explicitly encoded and printed.','That derivative is explicitly represented by the zero arrays.'],typ='scenario',assumptions=['The question asks only what the displayed program establishes, not whether some unspecified robot could execute the path.'])
